import math

def linear_worst(n):
    return n

def binary_worst(n):
    return 0 if n == 0 else math.floor(math.log2(n)) + 1

def compare(sizes):
    table = []
    for s in sizes:
        table.append([s, linear_worst(s), binary_worst(s)])
    return table
